import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import classList from 'flarum/common/utils/classList';
import { Card } from '../widgets/ui';
import { onChange, t } from '../util';
import { openShare } from '../share';
import Controls from './Controls';
let reload = null;
onChange(() => reload?.());
/**
 * The profile tab's list. Your own: every testimonial you wrote, at any stage, with what happened
 * to it and a way to edit, take it down or bring it back (and your Depot reviews, which you can
 * take out of the widgets). Someone else's: only what they posted under their full name, so a
 * profile never gives away an anonymous or first-name testimonial.
 */
class UserTestimonialsList extends Component {
  rows = [];
  loading = true;
  more = false;
  oninit(vnode) {
    super.oninit(vnode);
    reload = () => this.load(0);
    this.load(0);
  }
  onremove(vnode) {
    super.onremove(vnode);
    reload = null;
  }
  own() {
    return !!app.session.user && this.attrs.user === app.session.user;
  }
  load(offset) {
    this.loading = true;
    const filter = this.own() ? {
      mine: 1
    } : {
      user: this.attrs.user.id()
    };
    app.store.find('testimonials', {
      filter,
      page: {
        offset,
        limit: 24
      }
    }).then(rows => {
      this.rows = offset ? [...this.rows, ...rows] : [...rows];
      this.more = !!rows.payload?.links?.next;
    })
    // The request already showed its error; the list keeps what it had.
    .catch(() => {}).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
  view() {
    return m("div", {
      className: "UserTestimonials"
    }, this.own() && app.forum.attribute('testimonialsCanCreate') ? m("div", {
      className: "UserTestimonials-head"
    }, m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-pen",
      onclick: () => openShare()
    }, t('share.button'))) : null, this.list(), this.loading ? m(LoadingIndicator, null) : null, this.more && !this.loading ? m("div", {
      className: "TestimonialsPage-more"
    }, m(Button, {
      className: "Button",
      onclick: () => this.load(this.rows.length)
    }, t('page.load_more'))) : null);
  }
  list() {
    if (this.rows.length) {
      return m("div", {
        className: "TestimonialsPage-grid"
      }, this.rows.map(row => m(Card, {
        row: row,
        className: classList(row.status() && `is-${row.status()}`),
        footer: this.footer(row)
      })));
    }
    return this.loading ? null : m("p", {
      className: "TestimonialsPage-empty"
    }, this.own() ? t('profile.empty_own') : t('profile.empty'));
  }

  /** What happened to it (your own only), and its ⋯ menu. */
  footer(row) {
    const status = row.status();
    const label = !status ? null : status === 'approved' && row.hiddenByAuthor() ? 'hidden' : status === 'approved' && row.isFeatured() ? 'featured' : status;
    return m("div", {
      className: "UserTestimonials-foot"
    }, this.own() && label ? m("span", {
      className: classList('UserTestimonials-status', `is-${label}`)
    }, t(`profile.status.${label}`), status === 'declined' && row.declineReason() ? m("span", {
      className: "UserTestimonials-reason"
    }, row.declineReason()) : null, status === 'removed' ? m("span", {
      className: "UserTestimonials-reason"
    }, t('profile.removed_help')) : null) : m("span", null), m(Controls, {
      row: row
    }));
  }
}

/**
 * The profile tab. UserPage lives in a lazy chunk, so the page class is made once it's loaded;
 * the list is its own component (keyed by the member, so another profile starts afresh).
 */
let made = null;
export async function userTestimonialsPage() {
  if (made) return made;
  const mod = await flarum.reg.asyncModuleImport('flarum/forum/components/UserPage');
  const UserPage = mod.default || mod;
  made = class UserTestimonialsPage extends UserPage {
    oninit(vnode) {
      super.oninit(vnode);
      this.loadUser(m.route.param('username'));
    }
    content() {
      return this.user ? m(UserTestimonialsList, {
        key: this.user.id(),
        user: this.user
      }) : null;
    }
  };
  return made;
}